-- announcements
CREATE TABLE announcements (
    id                           NUMBER GENERATED BY DEFAULT AS IDENTITY,
    title                        VARCHAR2(200) NOT NULL,
    content                      CLOB NOT NULL,
    category                     VARCHAR2(40) NOT NULL DEFAULT 'General',
    priority                     VARCHAR2(20) NOT NULL DEFAULT 'Normal',
    target_audience              VARCHAR2(40) NOT NULL DEFAULT 'All',
    target_value                 VARCHAR2(100),
    published                    NUMBER(1) NOT NULL DEFAULT 0,
    published_at                 TIMESTAMP,
    expires_at                   TIMESTAMP,
    created_by                   NUMBER REFERENCES users(id),
    created_at                   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);

-- applications
CREATE TABLE applications (
    id                           NUMBER GENERATED BY DEFAULT AS IDENTITY,
    requisition_id               NUMBER NOT NULL REFERENCES job_requisitions(id),
    candidate_id                 NUMBER NOT NULL REFERENCES candidates(id),
    status                       VARCHAR2(20) NOT NULL DEFAULT 'Applied',
    notes                        CLOB,
    applied_date                 DATE NOT NULL,
    created_at                   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);

-- asset_assignments
CREATE TABLE asset_assignments (
    id                           NUMBER GENERATED BY DEFAULT AS IDENTITY,
    tenant_id                    VARCHAR2(60),
    asset_id                     NUMBER NOT NULL REFERENCES assets(id),
    employee_id                  NUMBER NOT NULL REFERENCES employees(id),
    status                       VARCHAR2(10) NOT NULL DEFAULT 'open',
    notes                        CLOB,
    assigned_by                  NUMBER REFERENCES users(id),
    assigned_at                  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    acknowledged_at              TIMESTAMP,
    closed_by                    NUMBER REFERENCES users(id),
    closed_at                    TIMESTAMP,
    close_reason                 VARCHAR2(20),
    return_condition             VARCHAR2(10),
    PRIMARY KEY (id)
);

CREATE INDEX ix_asset_asg_tenant_id_id ON asset_assignments (tenant_id, id);
CREATE INDEX ix_asset_assignments_asset_id ON asset_assignments (asset_id);
CREATE INDEX ix_asset_assignments_employee_id ON asset_assignments (employee_id);
CREATE INDEX ix_asset_assignments_tenant_id ON asset_assignments (tenant_id);

-- assets
CREATE TABLE assets (
    id                           NUMBER GENERATED BY DEFAULT AS IDENTITY,
    tenant_id                    VARCHAR2(60),
