    name                         VARCHAR2(160) NOT NULL,
    category                     VARCHAR2(60) NOT NULL DEFAULT 'General',
    description                  CLOB,
    serial_number                VARCHAR2(120),
    status                       VARCHAR2(20) NOT NULL DEFAULT 'in_stock',
    created_by                   NUMBER REFERENCES users(id),
    created_at                   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at                   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);

CREATE INDEX ix_assets_tag ON assets (tag);
CREATE INDEX ix_assets_tenant_id ON assets (tenant_id);
CREATE INDEX ix_assets_tenant_id_id ON assets (tenant_id, id);

