-- employees
CREATE TABLE employees (
    id                           NUMBER GENERATED BY DEFAULT AS IDENTITY,
    tenant_id                    VARCHAR2(60),
    employee_id                  VARCHAR2(50) NOT NULL UNIQUE,
    first_name                   VARCHAR2(100) NOT NULL,
    last_name                    VARCHAR2(100) NOT NULL,
    email                        VARCHAR2(255) NOT NULL UNIQUE,
    phone                        VARCHAR2(30),
    hire_date                    DATE NOT NULL,
    job_id                       NUMBER NOT NULL REFERENCES jobs(id),
    department_id                NUMBER NOT NULL REFERENCES departments(id),
    legal_entity_id              NUMBER,
    manager_id                   NUMBER REFERENCES employees(id),
    status                       VARCHAR2(20) NOT NULL DEFAULT 'Active',
    employment_type              VARCHAR2(30),
    termination_date             DATE,
    salary                       NUMBER(10,2),
    pan_number                   VARCHAR2(10),
    tax_regime                   VARCHAR2(10) NOT NULL DEFAULT 'new',
    pf_uan                       VARCHAR2(12),
    esi_number                   VARCHAR2(17),
    ifsc_code                    VARCHAR2(11),
    aadhaar_encrypted            CLOB,
    aadhaar_last4                VARCHAR2(4),
    aadhaar_masked               VARCHAR2(14),
    pan_verified_status          VARCHAR2(20),
    uan_verified_status          VARCHAR2(20),
    esi_verified_status          VARCHAR2(20),
    form11_json                  CLOB,
    nominee_json                 CLOB,
    created_at                   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at                   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);

